import os, json, subprocess
root = "E:\\0zhongqi"
def tree(p, cap=400):
    out = []
    for dp, dn, fn in os.walk(p):
        for f in fn:
            fp = os.path.join(dp, f)
            try: sz = os.path.getsize(fp)
            except Exception: sz = -1
            out.append([os.path.relpath(fp, p), sz])
            if len(out) >= cap: return out
    return out
def gitinfo(p):
    if not os.path.isdir(os.path.join(p, ".git")): return None
    o = {}
    for k, a in (("log", ["log", "--oneline", "-3"]), ("status", ["status", "--short"]), ("remote", ["remote", "-v"]), ("branch", ["branch", "--show-current"])):
        try:
            r = subprocess.run(["git", "-C", p] + a, capture_output=True, text=True, timeout=30)
            o[k] = (r.stdout + r.stderr)[:600]
        except Exception as e: o[k] = "ERR " + repr(e)[:100]
    return o
res = {}
