for d in ("zhongqi", "zhongqi-arena"):
    dp = os.path.join(root, d)
    res[d + "_git"] = gitinfo(dp)
    for sub in ("deliverable", "results"):
        sp = os.path.join(dp, sub)
        if os.path.isdir(sp): res[d + "/" + sub] = tree(sp, 200)
    for k in sorted(os.listdir(dp)):
        if k not in (".git", "code", "docs", "skills", "sources"):
            kp = os.path.join(dp, k)
            if os.path.isdir(kp) and k not in ("deliverable", "results"):
                res[d + "/" + k + "_top"] = sorted(os.listdir(kp))[:30]
