    res[d + "_git"] = gitinfo(os.path.join(root, d))
res["zhongqi_out_tree"] = tree(os.path.join(root, "zhongqi_out"))
res["zhongqi-arena_out_tree"] = tree(os.path.join(root, "zhongqi-arena_out"))
